/**
 * Grid-accelerated O(N) viscosity force computation pass.
 * Uses spatial grid for efficient neighbor lookup.
 *
 * @param {*} positionsBuffer Particle positions buffer.
 * @param {*} velocitiesBuffer Particle velocities buffer.
 * @param {*} densitiesBuffer Particle densities buffer.
 * @param {*} viscosityForcesBuffer Viscosity forces buffer.
 * @param {number} particleCount Number of particles.
 * @param {*} viscosity Viscosity kernel coefficient uniform.
 * @param {*} viscosityMu Viscosity coefficient uniform.
 * @param {*} h Smoothing radius uniform.
 * @param {*} mass Particle mass uniform.
 * @param {*} grid Spatial grid instance.
 * @param {boolean} is3D Whether simulation is 3D.
 * @param {boolean} debugEnabled Debug mode flag.
 * @param {*} debugActivatedBuffer Debug activation buffer (optional).
 * @param {*} debugCellIdBuffer Debug cell ID buffer (optional).
 * @returns {*} Compute node.
 */
export function computeViscosityPassGrid(positionsBuffer: any, velocitiesBuffer: any, densitiesBuffer: any, viscosityForcesBuffer: any, particleCount: number, viscosity: any, viscosityMu: any, h: any, mass: any, grid: any, is3D: boolean, debugEnabled: boolean, debugActivatedBuffer: any, debugCellIdBuffer: any): any;
